export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly cb: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.cb = circuitBreaker ?? new CircuitBreaker();
  }

  async get<T>(url: string, options: RequestOptions = {}): Promise<T> {
    const controller = new AbortController();
    const timer = options.timeoutMs === undefined ? undefined : setTimeout(() => controller.abort(), options.timeoutMs);
    try {
      const response = await this.cb.execute(async () => {
        let res: Response;
        try {
          res = await fetch(url, { method: 'GET', headers: options.headers, signal: controller.signal });
        } catch (error) {
          if (error instanceof Error && error.name === 'AbortError') {
            throw new ApiError(`Request timed out after ${options.timeoutMs}ms`, 408);
          }
          throw new ApiError(error instanceof Error ? error.message : 'Network request failed', 0);
        }
        if (!res.ok) {
          const message = await res.text().catch(() => '');
          throw new ApiError(message || res.statusText || `HTTP ${res.status}`, res.status);
        }
        return res;
      });
      return await response.json() as T;
    } catch (error) {
      if (error instanceof ApiError) throw error;
      if (error instanceof Error && error.name === 'AbortError') {
        throw new ApiError(`Request timed out after ${options.timeoutMs}ms`, 408);
      }
      throw error;
    } finally {
      if (timer !== undefined) clearTimeout(timer);
    }
  }
}

export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class CircuitBreaker {
  private currentState: CircuitState = 'CLOSED';
  private failureCount = 0;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;
  private halfOpenAttempt = false;
  private resetTimer?: ReturnType<typeof setTimeout>;

  constructor(options: CircuitBreakerOptions = {}) {
    this.failureThreshold = options.failureThreshold ?? 3;
    this.resetTimeoutMs = options.resetTimeoutMs ?? 30000;
  }

  get state(): CircuitState { return this.currentState; }

  getState(): CircuitState { return this.currentState; }

  recordSuccess(): void {
    if (this.currentState === 'HALF_OPEN') {
      this.currentState = 'CLOSED';
      this.failureCount = 0;
      this.halfOpenAttempt = false;
      this.clearTimer();
    } else if (this.currentState === 'CLOSED') {
      this.failureCount = 0;
    }
  }

  recordFailure(): void {
    if (this.currentState === 'HALF_OPEN') {
      this.open();
    } else if (this.currentState === 'CLOSED') {
      this.failureCount++;
      if (this.failureCount >= this.failureThreshold) {
        this.open();
      }
    }
  }

  execute<T>(action: () => Promise<T>): Promise<T> {
    if (this.currentState === 'OPEN') {
      return Promise.reject(new Error('Circuit breaker is OPEN'));
    }

    if (this.currentState === 'HALF_OPEN') {
      if (this.halfOpenAttempt) {
        return Promise.reject(new Error('Circuit breaker HALF_OPEN; retry later'));
      }
      this.halfOpenAttempt = true;
    }

    return Promise.resolve()
      .then(action)
      .then(result => { this.recordSuccess(); return result; })
      .catch(error => { this.recordFailure(); throw error; });
  }

  private open(): void {
    this.currentState = 'OPEN';
    this.halfOpenAttempt = false;
    this.clearTimer();
    this.resetTimer = setTimeout(() => {
      if (this.currentState === 'OPEN') {
        this.currentState = 'HALF_OPEN';
      }
    }, this.resetTimeoutMs);
  }

  private clearTimer(): void {
    if (this.resetTimer) {
      clearTimeout(this.resetTimer);
      this.resetTimer = undefined;
    }
  }
}

